'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase'
import { getTBAData, TBATeam } from '@/lib/tba'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Switch } from '@/components/ui/switch'
import { Loader2, AlertCircle, CheckCircle2, Globe, MapPin, Gauge, Weight, ArrowUpCircle, Zap, Shield, Settings, Activity } from 'lucide-react'
import { Badge } from '@/components/ui/badge'

export default function PitScoutingForm() {
    const [loading, setLoading] = useState(false)
    const [tbaLoading, setTbaLoading] = useState(false)
    const [tbaTeam, setTbaTeam] = useState<TBATeam | null>(null)
    const [formData, setFormData] = useState({
        team_number: '',
        event_key: '2025ilpe',
        weight: '',
        fuel_capacity: '',
        top_speed: '',
        fuel_per_second: '',
        primary_role: 'Offense',
        climb_level: '1',
        climbs_in_auto: false,
        obstacle_handling: 'None',
        drive_train: 'Swerve',
        scout_name: '',
        notes: '',
    })

    const supabase = createClient()

    useEffect(() => {
        const fetchTeamFromTBA = async () => {
            if (formData.team_number.length >= 1) {
                setTbaLoading(true)
                try {
                    const data = await getTBAData(`/team/frc${formData.team_number}`)
                    setTbaTeam(data)
                } catch (err) {
                    console.error('TBA Fetch Error:', err)
                    setTbaTeam(null)
                } finally {
                    setTbaLoading(false)
                }
            } else {
                setTbaTeam(null)
            }
        }

        const timer = setTimeout(() => {
            if (formData.team_number) {
                fetchTeamFromTBA()
            }
        }, 800) // Debounce

        return () => clearTimeout(timer)
    }, [formData.team_number])

    const handleInputChange = (field: string, value: any) => {
        setFormData((prev) => ({ ...prev, [field]: value }))
    }

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        try {
            const { error } = await supabase.from('pit_scouting').upsert([
                {
                    team_number: parseInt(formData.team_number),
                    event_key: formData.event_key,
                    robot_weight: parseFloat(formData.weight),
                    fuel_capacity: parseInt(formData.fuel_capacity),
                    top_speed: parseFloat(formData.top_speed),
                    fuel_per_second: parseFloat(formData.fuel_per_second),
                    primary_role: formData.primary_role,
                    climb_level: parseInt(formData.climb_level),
                    climbs_in_auto: formData.climbs_in_auto,
                    obstacle_handling: formData.obstacle_handling,
                    drive_train_type: formData.drive_train,
                    scout_name: formData.scout_name,
                    comments: formData.notes,
                },
            ], { onConflict: 'team_number, event_key' })

            if (error) {
                console.error('Error submitting pit data:', error)
                alert('Error submitting data: ' + error.message)
            } else {
                alert('Pit data saved successfully!')
            }
        } catch (err) {
            console.error('Unexpected error:', err)
        } finally {
            setLoading(false)
        }
    }

    return (
        <Card className="max-w-4xl mx-auto overflow-hidden shadow-xl border-primary/20 bg-background/50 backdrop-blur-sm">
            <CardHeader className="bg-primary/10 border-b border-primary/20 pb-8">
                <div className="flex flex-col md:flex-row justify-between items-start gap-4">
                    <div className="space-y-1">
                        <CardTitle className="text-3xl font-black tracking-tight text-primary">Mechanical Specs</CardTitle>
                        <CardDescription className="text-base">Static Robot Capabilities (Pit Scouting)</CardDescription>
                    </div>
                    {tbaTeam ? (
                        <Badge variant="secondary" className="bg-primary/20 text-primary border-primary/30 flex gap-2 items-center px-4 py-2 text-sm font-bold animate-in fade-in zoom-in">
                            <CheckCircle2 className="h-4 w-4" />
                            TBA Verified: {tbaTeam.nickname}
                        </Badge>
                    ) : (
                        <Badge variant="outline" className="opacity-50 flex gap-2 items-center px-4 py-2 text-sm">
                            <AlertCircle className="h-4 w-4" />
                            Awaiting Team #
                        </Badge>
                    )}
                </div>
            </CardHeader>
            <CardContent className="pt-8 space-y-8">
                {/* ID & Scout Section */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="space-y-2">
                        <Label htmlFor="team_number" className="text-xs uppercase font-black text-muted-foreground flex items-center gap-2">
                            <MapPin className="h-3 w-3" /> Team Number
                        </Label>
                        <div className="relative">
                            <Input
                                id="team_number"
                                placeholder="e.g. 254"
                                value={formData.team_number}
                                onChange={(e) => handleInputChange('team_number', e.target.value)}
                                className="h-12 text-lg font-bold border-2 focus:ring-primary"
                            />
                            {tbaLoading && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 h-5 w-5 animate-spin text-primary" />}
                        </div>
                    </div>
                    <div className="space-y-2">
                        <Label htmlFor="event_key" className="text-xs uppercase font-black text-muted-foreground">Event Key</Label>
                        <Input
                            id="event_key"
                            value={formData.event_key}
                            onChange={(e) => handleInputChange('event_key', e.target.value)}
                            className="h-12 font-mono uppercase"
                        />
                    </div>
                    <div className="space-y-2">
                        <Label htmlFor="scout_name" className="text-xs uppercase font-black text-muted-foreground flex items-center gap-2">
                            Scout Name
                        </Label>
                        <Input
                            id="scout_name"
                            placeholder="Your Name"
                            value={formData.scout_name}
                            onChange={(e) => handleInputChange('scout_name', e.target.value)}
                            className="h-12"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                    {/* Numerical Stats */}
                    <div className="space-y-2 p-4 rounded-2xl bg-muted/50 border border-border shadow-sm">
                        <Label className="text-[10px] uppercase font-bold text-muted-foreground flex items-center gap-1.5 mb-2">
                            <Weight className="h-4 w-4 text-primary" /> Weight (lbs)
                        </Label>
                        <Input
                            type="number"
                            value={formData.weight}
                            onChange={(e) => handleInputChange('weight', e.target.value)}
                            placeholder="125"
                            className="text-xl font-bold border-none bg-transparent h-8"
                        />
                    </div>
                    <div className="space-y-2 p-4 rounded-2xl bg-muted/50 border border-border shadow-sm">
                        <Label className="text-[10px] uppercase font-bold text-muted-foreground flex items-center gap-1.5 mb-2">
                            <Activity className="h-4 w-4 text-primary" /> Fuel Capacity
                        </Label>
                        <Input
                            type="number"
                            value={formData.fuel_capacity}
                            onChange={(e) => handleInputChange('fuel_capacity', e.target.value)}
                            placeholder="20"
                            className="text-xl font-bold border-none bg-transparent h-8"
                        />
                    </div>
                    <div className="space-y-2 p-4 rounded-2xl bg-muted/50 border border-border shadow-sm">
                        <Label className="text-[10px] uppercase font-bold text-muted-foreground flex items-center gap-1.5 mb-2">
                            <Gauge className="h-4 w-4 text-primary" /> Top Speed (ft/s)
                        </Label>
                        <Input
                            type="number"
                            value={formData.top_speed}
                            onChange={(e) => handleInputChange('top_speed', e.target.value)}
                            placeholder="15.5"
                            className="text-xl font-bold border-none bg-transparent h-8"
                        />
                    </div>
                    <div className="space-y-2 p-4 rounded-2xl bg-muted/50 border border-border shadow-sm">
                        <Label className="text-[10px] uppercase font-bold text-muted-foreground flex items-center gap-1.5 mb-2">
                            <Zap className="h-4 w-4 text-primary" /> Fuel / Second
                        </Label>
                        <Input
                            type="number"
                            value={formData.fuel_per_second}
                            onChange={(e) => handleInputChange('fuel_per_second', e.target.value)}
                            placeholder="1.2"
                            className="text-xl font-bold border-none bg-transparent h-8"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Role & Drive Train */}
                    <div className="space-y-6">
                        <div className="space-y-3">
                            <Label className="text-xs uppercase font-black text-muted-foreground flex items-center gap-2">
                                <Shield className="h-4 w-4" /> Primary Role
                            </Label>
                            <Select onValueChange={(v) => handleInputChange('primary_role', v)} value={formData.primary_role}>
                                <SelectTrigger className="h-12 border-2">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="Offense">Offense (Scoring Focus)</SelectItem>
                                    <SelectItem value="Defense">Defense (Shut-down Focus)</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="space-y-3 p-6 rounded-2xl border-2 border-primary/10 bg-primary/5">
                            <div className="flex items-center justify-between">
                                <div className="space-y-1">
                                    <Label className="text-sm font-black flex items-center gap-2">
                                        <Settings className="h-4 w-4" /> Drive Train
                                    </Label>
                                    <div className="text-xs text-muted-foreground">Current Config: <span className="font-bold text-primary italic uppercase">{formData.drive_train}</span></div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className="text-xs font-bold text-muted-foreground">Tank</span>
                                    <Switch
                                        checked={formData.drive_train === 'Swerve'}
                                        onCheckedChange={(checked) => handleInputChange('drive_train', checked ? 'Swerve' : 'Tank')}
                                    />
                                    <span className="text-xs font-bold text-primary">Swerve</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Climb Specs */}
                    <div className="space-y-6">
                        <div className="space-y-3">
                            <Label className="text-xs uppercase font-black text-muted-foreground flex items-center gap-2">
                                <ArrowUpCircle className="h-4 w-4" /> Climb Performance
                            </Label>
                            <Select onValueChange={(v) => handleInputChange('climb_level', v)} value={formData.climb_level}>
                                <SelectTrigger className="h-12 border-2">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="1">Level 1 (Lowest Hanging)</SelectItem>
                                    <SelectItem value="2">Level 2 (Mid Bar)</SelectItem>
                                    <SelectItem value="3">Level 3 (Top Bar)</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="flex items-center justify-between p-6 rounded-2xl border-2 border-dashed border-primary/20 bg-muted/30">
                            <div className="space-y-1">
                                <Label className="text-sm font-black">Climbs in Auto?</Label>
                                <div className="text-xs text-muted-foreground">Does the robot climb during the first 15s?</div>
                            </div>
                            <Switch
                                checked={formData.climbs_in_auto}
                                onCheckedChange={(checked) => handleInputChange('climbs_in_auto', checked)}
                            />
                        </div>
                    </div>
                </div>

                {/* Obstacle Handling */}
                <div className="space-y-3">
                    <Label className="text-xs uppercase font-black text-muted-foreground">Obstacle Handling / Pathing</Label>
                    <Select onValueChange={(v) => handleInputChange('obstacle_handling', v)} value={formData.obstacle_handling}>
                        <SelectTrigger className="h-12 border-2">
                            <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="None">None (Fixed Path)</SelectItem>
                            <SelectItem value="Trench">Trench (Low Clearance)</SelectItem>
                            <SelectItem value="Bump">Bump (Off-road/Clears Level Changes)</SelectItem>
                            <SelectItem value="Both">Both (Highly Mobile)</SelectItem>
                        </SelectContent>
                    </Select>
                </div>

                <div className="space-y-3">
                    <Label htmlFor="notes" className="text-xs uppercase font-black text-muted-foreground">Internal Scouting Notes</Label>
                    <Textarea
                        id="notes"
                        placeholder="Build quality, specific driver quirks, or critical weaknesses..."
                        value={formData.notes}
                        onChange={(e) => handleInputChange('notes', e.target.value)}
                        className="min-h-[120px] text-base border-2 focus:ring-primary"
                    />
                </div>
            </CardContent>
            <CardFooter className="bg-primary/5 border-t border-primary/10 p-8">
                <Button
                    className="w-full h-16 text-xl font-black uppercase tracking-widest shadow-lg hover:shadow-primary/20 transition-all hover:scale-[1.01]"
                    onClick={handleSubmit}
                    disabled={loading || !formData.team_number}
                >
                    {loading ? <Loader2 className="mr-3 h-6 w-6 animate-spin" /> : <Settings className="mr-3 h-6 w-6" />}
                    Lock in Specifications
                </Button>
            </CardFooter>
        </Card>
    )
}
