'use client'

import { useState } from 'react'
import PitScoutingList from '@/components/scouting/PitScoutingList'
import PitScoutingForm from '@/components/scouting/PitScoutingForm'
import { Button } from '@/components/ui/button'
import { Plus, List } from 'lucide-react'

export default function PitScoutingPage() {
    const [view, setView] = useState<'list' | 'form'>('list')

    return (
        <div className="container py-8 mx-auto px-4">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold">Pit Scouting</h1>
                <Button variant="outline" onClick={() => setView(view === 'list' ? 'form' : 'list')}>
                    {view === 'list' ? (
                        <><Plus className="h-4 w-4 mr-2" /> New Entry</>
                    ) : (
                        <><List className="h-4 w-4 mr-2" /> View List</>
                    )}
                </Button>
            </div>

            {view === 'form' ? <PitScoutingForm /> : <PitScoutingList />}
        </div>
    )
}
